/*
 * Turns a studio session into OneTake page scripts: one file per page load
 * (NN-<page>.js) plus render.sh. Generated files are plain OneTake scripts:
 * edit them by hand or with an AI, or keep using the studio.
 */
const fs = require('fs');
const path = require('path');

const q = v => JSON.stringify(v == null ? '' : String(v));
const SHAPES = new Set(['circle', 'box', 'underline', 'arrow', 'spotlight', 'pulse']);

function stepCode(s) {
  switch (s.type) {
    case 'click': return `.click(${q(s.target)})`;
    case 'type': return `.type(${q(s.target)}, ${q(s.value)}${s.enter ? ', { enter: true }' : ''})`;
    case 'select': return `.select(${q(s.target)}, ${q(s.value)})`;
    case 'check': return `.check(${q(s.target)}${s.state === false ? ', false' : ''})`;
    case 'zoom': return s.seconds ? `.zoom(${q(s.target)}, ${+s.seconds})` : `.zoom(${q(s.target)})`;
    case 'zoomOut': return '.zoomOut()';
    case 'highlight': {
      const shape = SHAPES.has(s.shape) ? s.shape : 'circle';
      const opts = [];
      if (s.label) opts.push(`label: ${q(s.label)}`);
      opts.push(`duration: ${+(s.duration || (shape === 'spotlight' ? 2200 : 2000))}`);
      return `.${shape}(${q(s.target)}, { ${opts.join(', ')} })`;
    }
    case 'caption': return `.caption(${q(s.text)}, { duration: ${+(s.duration || 3000)} })`;
    case 'wait': return `.wait(${+(s.ms || 1000)})`;
    default: return null;
  }
}

function slug(url, i) {
  try {
    const p = new URL(url).pathname.replace(/\/+$/, '');
    const name = p.split('/').filter(Boolean).filter(x => !/^[A-Za-z0-9]{10,}$|^\d+$/.test(x)).slice(-2).join('-');
    return (i + 1) + '-' + (name || 'start').toLowerCase().replace(/[^a-z0-9-]+/g, '-').slice(0, 40);
  } catch (e) { return (i + 1) + '-page'; }
}

/** Split steps into pages: [{ url, steps, leaveTo }] where leaveTo is set when the next page needs a direct visit. */
function pages(session) {
  const out = [{ url: session.url, steps: [] }];
  for (const s of session.steps) {
    if (s.type === 'page') {
      if (s.direct) out[out.length - 1].leaveTo = s.url;
      out.push({ url: s.url, steps: [] });
    } else out[out.length - 1].steps.push(s);
  }
  return out;
}

function scriptFor(page, i, total) {
  const lines = [
    `// Page ${i + 1} of ${total}: ${page.url}`,
    '// Generated by OneTake Studio. `take` is a ready OneTake instance: edit freely.',
    ''
  ];
  const body = [];
  for (const s of page.steps) {
    if (s.type === 'note') { body.push(`  // ${String(s.text).replace(/\n/g, ' ')}`); continue; }
    const code = stepCode(s);
    if (code) body.push('  ' + code);
  }
  if (page.leaveTo) body.push(`  .run(() => { location.href = ${q(page.leaveTo)}; })`);
  if (i === total - 1) body.push('  .wait(1500)');
  // Comments may sit between chained calls; the statement ends with `;` after the last line.
  if (!body.some(l => !l.trim().startsWith('//'))) body.push('  .wait(500)');
  if (body[body.length - 1].trim().startsWith('//')) body.push('  ;');
  else body[body.length - 1] += ';';
  lines.push('take', ...body);
  return lines.join('\n') + '\n';
}

function generate(session, outDir, opts) {
  opts = opts || {};
  const data = session.data;
  if (!data.url) throw new Error('Nothing recorded yet. Press Record first.');
  fs.mkdirSync(outDir, { recursive: true });
  for (const f of data.generated || []) {                    // remove files we generated last time
    const p = path.join(outDir, f);
    if (fs.existsSync(p)) fs.unlinkSync(p);
  }
  const list = pages(data);
  const files = list.map((p, i) => {
    const name = slug(p.url, i) + '.js';
    fs.writeFileSync(path.join(outDir, name), scriptFor(p, i, list.length));
    return name;
  });

  const vp = data.viewport || { width: 1440, height: 900 };
  const recordJs = path.relative(outDir, path.join(__dirname, '..', 'record.js')) || 'record.js';
  const sh = [
    '#!/usr/bin/env bash',
    '# Renders this studio session to a 60 fps MP4. Generated by OneTake Studio.',
    '#   bash render.sh            # full quality (2x)',
    '#   SCALE=1 bash render.sh    # quicker preview',
    'set -euo pipefail',
    'HERE="$(cd "$(dirname "$0")" && pwd)"',
    'STORAGE=(); [ -f "$HERE/auth.json" ] && STORAGE=(--storage "$HERE/auth.json")',
    `node "$HERE/${recordJs}" --url ${q(data.url)} \\`,
    '  ${STORAGE[@]+"${STORAGE[@]}"} \\',
    ...files.map(f => `  --script "$HERE/${f}" \\`),
    `  --width ${vp.width} --height ${vp.height} --scale "\${SCALE:-2}" --fps 60 --seed 7 \\`,
    '  --out "$HERE/videos" --name demo'
  ].join('\n') + '\n';
  fs.writeFileSync(path.join(outDir, 'render.sh'), sh, { mode: 0o755 });

  data.generated = files;
  session.save();
  return { files, dir: outDir };
}

module.exports = { generate, pages, stepCode, scriptFor };
